    const worktreePath = path.join(this.getWorktreesBaseDir(), taskId);
    if (!fs.existsSync(worktreePath)) return false;
    try {
      const status = execFileSync("git", ["status", "--porcelain", "--ignored=matching", "--untracked-files=all"], {
